mapper.update:
UPDATE plan_task SET completed = #{completed}, task_icon = #{taskIcon}, task_color = #{taskColor}
WHERE id = #{id} AND completed != 1
AND NOT EXISTS (SELECT 1 FROM checkin c WHERE c.task_id = plan_task.id AND c.status = 'pending')

mapper.select:
SELECT COUNT(DISTINCT pt.day_number) FROM plan_task pt
JOIN plan p ON pt.plan_id = p.id
WHERE p.user_id = #{userId}
AND pt.task_date <= #{today}

SELECT COUNT(DISTINCT day_number) FROM plan_task
WHERE plan_id = #{planId} AND completed = 0 AND task_date <= #{today}
AND NOT EXISTS (SELECT 1 FROM checkin c WHERE c.task_id = plan_task.id AND c.status = 'pending')
